H.background();
const n = Math.max(0, Math.round(P.n));
const cx = H.W * 0.52, cy = H.H * 0.54, R = Math.min(H.W, H.H) * 0.30;
H.line(cx - R - 30, cy, cx + R + 30, cy, { color: H.colors.axis, width: 1.2 });
H.line(cx, cy - R - 30, cx, cy + R + 30, { color: H.colors.axis, width: 1.2 });
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 1.5 });
H.text("real", cx + R + 6, cy - 6, { color: H.colors.sub, size: 12 });
H.text("imag", cx + 6, cy - R - 10, { color: H.colors.sub, size: 12 });
const pts = [[1,0,"1"],[0,1,"i"],[-1,0,"-1"],[0,-1,"-i"]];
for (let k = 0; k < 4; k++) {
  const px = cx + R * pts[k][0], py = cy - R * pts[k][1];
  H.circle(px, py, 5, { fill: H.colors.grid, stroke: H.colors.sub, width: 1 });
  H.text(pts[k][2], px + 8 * pts[k][0] + (pts[k][0] === 0 ? -4 : 4), py - 8 * pts[k][1] - 2, { color: H.colors.sub, size: 13 });
}
const sweep = n + (t % 4);
const ang = sweep * Math.PI / 2;
const hx = cx + R * Math.cos(ang), hy = cy - R * Math.sin(ang);
H.line(cx, cy, hx, hy, { color: H.colors.accent2, width: 2 });
H.circle(hx, hy, 7 + Math.sin(t * 4), { fill: H.colors.warn });
const rem = n % 4;
const vals = [["1","real 1"],["i","up the imag axis"],["-1","real -1"],["-i","down the imag axis"]];
const rx = cx + R * Math.cos(rem * Math.PI / 2), ry = cy - R * Math.sin(rem * Math.PI / 2);
